import os
import boto3
from botocore.exceptions import ClientError
from typing import Dict, Any, Optional

class AWSSecretsManagerClient:
    def __init__(self):
        self.client = boto3.client('secretsmanager')

    def get_secret(self, secret_name: str, version_id: Optional[str] = None, version_stage: Optional[str] = None) -> Dict[str, Any]:
        try:
            kwargs = {'SecretId': secret_name}
            if version_id:
                kwargs['VersionId'] = version_id
            if version_stage:
                kwargs['VersionStage'] = version_stage

            get_secret_value_response = self.client.get_secret_value(**kwargs)
            return get_secret_value_response
        except ClientError as e:
            print(f"Error fetching secret {secret_name}: {e}")
            raise

    def list_secrets(self, max_results: int = 100) -> Dict[str, Any]:
        try:
            list_secrets_response = self.client.list_secrets(MaxResults=max_results)
            return list_secrets_response
        except ClientError as e:
            print(f"Error listing secrets: {e}")
            raise

    def update_secret_version_stage(self, secret_id: str, version_stage: str, secret_string: Optional[str] = None, secret_binary: Optional[bytes] = None) -> Dict[str, Any]:
        try:
            kwargs = {
                'SecretId': secret_id,
                'VersionStages': [version_stage]
            }
            if secret_string is not None:
                kwargs['SecretString'] = secret_string
            if secret_binary is not None:
                kwargs['SecretBinary'] = secret_binary

            update_secret_response = self.client.put_secret_value(**kwargs)
            return update_secret_response
        except ClientError as e:
            print(f"Error updating secret version stage for {secret_id}: {e}")
            raise

import os
import boto3
from typing import List, Dict, Any
from botocore.exceptions import ClientError
from security_models import AuditNote

class AWSComprehendClient:
    def __init__(self):
        self.client = boto3.client('comprehend')

    def detect_sentiment(self, text: str, language_code: str = 'en') -> Dict[str, Any]:
        try:
            response = self.client.detect_sentiment(Text=text, LanguageCode=language_code)
            return response
        except ClientError as e:
            print(f"Error detecting sentiment: {e}")
            raise

def check_secret_label_safety(audit_notes: List[AuditNote]) -> Dict[str, Any]:
    comprehend_client = AWSComprehendClient()
    safety_report = {}

    for note in audit_notes:
        unsafe_findings = []
        # Check content for unsafe text
        if note.content:
            sentiment_response = comprehend_client.detect_sentiment(note.content)
            if sentiment_response.get('Sentiment') in ['NEGATIVE', 'MIXED']:
                unsafe_findings.append({'type': 'content_sentiment', 'sentiment': sentiment_response.get('Sentiment')})

        # Check labels for unsafe text
        if note.labels:
            for key, value in note.labels.items():
                sentiment_response_key = comprehend_client.detect_sentiment(key)
                if sentiment_response_key.get('Sentiment') in ['NEGATIVE', 'MIXED']:
                    unsafe_findings.append({'type': 'label_key_sentiment', 'label_key': key, 'sentiment': sentiment_response_key.get('Sentiment')})

                sentiment_response_value = comprehend_client.detect_sentiment(value)
                if sentiment_response_value.get('Sentiment') in ['NEGATIVE', 'MIXED']:
                    unsafe_findings.append({'type': 'label_value_sentiment', 'label_value': value, 'sentiment': sentiment_response_value.get('Sentiment')})

        if unsafe_findings:
            safety_report[note.note_id] = unsafe_findings

    return safety_report

import os
import boto3
import json
from typing import List, Dict, Any
from botocore.exceptions import ClientError
from security_models import AuditNote

class AWSBedrockClient:
    def __init__(self):
        self.client = boto3.client('bedrock-runtime')
        self.model_id = 'amazon.titan-embed-text-v1'  # Example embedding model ID

    def get_text_embedding(self, text: str) -> List[float]:
        try:
            body = json.dumps({"inputText": text})
            response = self.client.invoke_model(
                body=body,
                modelId=self.model_id,
                accept='application/json',
                contentType='application/json'
            )
            response_body = json.loads(response.get('body').read())
            return response_body.get('embedding')
        except ClientError as e:
            print(f"Error getting text embedding: {e}")
            raise

def embed_secret_audit_notes(audit_notes: List[AuditNote]) -> Dict[str, List[float]]:
    bedrock_client = AWSBedrockClient()
    embeddings = {}
    for note in audit_notes:
        if note.content:
            embeddings[note.note_id] = bedrock_client.get_text_embedding(note.content)
    return embeddings

import os
import boto3
from typing import List, Dict, Any
from botocore.exceptions import ClientError
from security_models import AuditNote

class AWSTranslateClient:
    def __init__(self):
        self.client = boto3.client('translate')

    def translate_text(self, text: str, source_language_code: str, target_language_code: str) -> str:
        try:
            response = self.client.translate_text(
                Text=text,
                SourceLanguageCode=source_language_code,
                TargetLanguageCode=target_language_code
            )
            return response.get('TranslatedText')
        except ClientError as e:
            print(f"Error translating text: {e}")
            raise

def translate_runbook_notes(audit_notes: List[AuditNote], target_language: str = 'es') -> Dict[str, str]:
    translate_client = AWSTranslateClient()
    translated_notes = {}
    for note in audit_notes:
        if note.content:
            translated_text = translate_client.translate_text(
                text=note.content,
                source_language_code='en',  # Assuming English as source, can be extended to detect language
                target_language_code=target_language
            )
            translated_notes[note.note_id] = translated_text
    return translated_notes
